class Solution {long cross(int[] a,int[] b,int[] p){return ((long)b[0]-a[0])*((long)p[1]-a[1])-((long)b[1]-a[1])*((long)p[0]-a[0]);}public boolean solve(int[][] polygon,int[] point){boolean inside=false;for(int i=0;i<polygon.length;i++){int[] a=polygon[i],b=polygon[(i+1)%polygon.length];if(cross(a,b,point)==0&&point[0]>=Math.min(a[0],b[0])&&point[0]<=Math.max(a[0],b[0])&&point[1]>=Math.min(a[1],b[1])&&point[1]<=Math.max(a[1],b[1]))return true;if((a[1]>point[1])!=(b[1]>point[1])){long left=((long)b[0]-a[0])*((long)point[1]-a[1]),right=((long)point[0]-a[0])*((long)b[1]-a[1]);if(b[1]>a[1]?left>right:left<right)inside=!inside;}}return inside;}}